await check("all-award-frames-green-and-moving",async()=>{
  await page.setViewportSize({width:1536,height:1024});
  await mode("baseline");
  await page.emulateMedia({reducedMotion:"no-preference"});
  const frames=await page.locator(".sl-avatar-frame").evaluateAll(els=>els.map(el=>({color:getComputedStyle(el).borderTopColor,width:getComputedStyle(el).borderTopWidth})));
  assert(frames.length>=5);
  assert(frames.every(frame=>frame.color==="rgb(196, 255, 54)"&&parseFloat(frame.width)>=2),JSON.stringify(frames));
  const moving=page.locator(".sl-podium-portrait .sl-avatar-frame,.sl-self .sl-avatar-frame");
  const before=await moving.evaluateAll(els=>els.map(el=>({name:getComputedStyle(el,"::after").animationName,state:getComputedStyle(el,"::after").animationPlayState,opacity:getComputedStyle(el,"::after").opacity,transform:getComputedStyle(el,"::after").transform})));
  assert.equal(before.length,5);
  assert(before.every(frame=>frame.name==="sl-ring-flow"&&frame.state==="running"&&frame.opacity==="1"));
  await page.waitForTimeout(250);
  const after=await moving.evaluateAll(els=>els.map(el=>getComputedStyle(el,"::after").transform));
  assert(after.every((transform,i)=>transform!==before[i].transform));
  await page.emulateMedia({reducedMotion:"reduce"});
  const reduced=await moving.evaluateAll(els=>els.map(el=>({animation:getComputedStyle(el,"::after").animationName,border:getComputedStyle(el).borderTopColor})));
  assert(reduced.every(frame=>frame.animation==="none"&&frame.border==="rgb(196, 255, 54)"));
  return {frames,before,after,reduced};
});
